class Component extends DCLogic {
  state = {
    zoomOpen1: false,
    scale1: 1, offsetX1: 0, offsetY1: 0, dragging1: false,
    dragStartX1: 0, dragStartY1: 0, dragOffsetStartX1: 0, dragOffsetStartY1: 0,
    zoomOpen5: false,
    scale5: 1, offsetX5: 0, offsetY5: 0, dragging5: false,
    dragStartX5: 0, dragStartY5: 0, dragOffsetStartX5: 0, dragOffsetStartY5: 0
  };

  focusClose1 = () => {
    const closeBtn = document.querySelector('[data-zoom-dialog="colombia-banco-de-panama-1-peso"] [data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose1);
  };
  focusTrigger1 = () => {
    const trigger = document.querySelector('[data-zoom-trigger="colombia-banco-de-panama-1-peso"]');
    if (trigger) trigger.focus();
  };
  openZoom1 = () => {
    this.setState({ zoomOpen1: true, scale1: 1, offsetX1: 0, offsetY1: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose1));
  };
  closeZoom1 = () => {
    this.setState({ zoomOpen1: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTrigger1));
  };
  zoomIn1 = () => this.setState(s => ({ scale1: Math.min(4, Math.round((s.scale1 + 0.5) * 10) / 10) }));
  zoomOut1 = () => this.setState(s => {
    const next = Math.max(1, Math.round((s.scale1 - 0.5) * 10) / 10);
    return { scale1: next, offsetX1: next === 1 ? 0 : s.offsetX1, offsetY1: next === 1 ? 0 : s.offsetY1 };
  });
  onWheel1 = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale1 + delta) * 100) / 100));
      return { scale1: next, offsetX1: next === 1 ? 0 : s.offsetX1, offsetY1: next === 1 ? 0 : s.offsetY1 };
    });
  };
  onPointerDown1 = (e) => {
    if (this.state.scale1 <= 1) return;
    this.setState({ dragging1: true, dragStartX1: e.clientX, dragStartY1: e.clientY, dragOffsetStartX1: this.state.offsetX1, dragOffsetStartY1: this.state.offsetY1 });
  };
  onPointerMove1 = (e) => {
    if (!this.state.dragging1) return;
    const dx = e.clientX - this.state.dragStartX1;
    const dy = e.clientY - this.state.dragStartY1;
    this.setState({ offsetX1: this.state.dragOffsetStartX1 + dx, offsetY1: this.state.dragOffsetStartY1 + dy });
  };
  onPointerUp1 = () => this.setState({ dragging1: false });

  focusClose5 = () => {
    const closeBtn = document.querySelector('[data-zoom-dialog="colombia-banco-de-panama-5-pesos"] [data-zoom-close]');
    if (closeBtn) { closeBtn.focus(); return; }
    requestAnimationFrame(this.focusClose5);
  };
  focusTrigger5 = () => {
    const trigger = document.querySelector('[data-zoom-trigger="colombia-banco-de-panama-5-pesos"]');
    if (trigger) trigger.focus();
  };
  openZoom5 = () => {
    this.setState({ zoomOpen5: true, scale5: 1, offsetX5: 0, offsetY5: 0 });
    requestAnimationFrame(() => requestAnimationFrame(this.focusClose5));
  };
  closeZoom5 = () => {
    this.setState({ zoomOpen5: false });
    requestAnimationFrame(() => requestAnimationFrame(this.focusTrigger5));
  };
  zoomIn5 = () => this.setState(s => ({ scale5: Math.min(4, Math.round((s.scale5 + 0.5) * 10) / 10) }));
  zoomOut5 = () => this.setState(s => {
    const next = Math.max(1, Math.round((s.scale5 - 0.5) * 10) / 10);
    return { scale5: next, offsetX5: next === 1 ? 0 : s.offsetX5, offsetY5: next === 1 ? 0 : s.offsetY5 };
  });
  onWheel5 = (e) => {
    e.preventDefault();
    const delta = e.deltaY > 0 ? -0.25 : 0.25;
    this.setState(s => {
      const next = Math.min(4, Math.max(1, Math.round((s.scale5 + delta) * 100) / 100));
      return { scale5: next, offsetX5: next === 1 ? 0 : s.offsetX5, offsetY5: next === 1 ? 0 : s.offsetY5 };
    });
  };
  onPointerDown5 = (e) => {
    if (this.state.scale5 <= 1) return;
    this.setState({ dragging5: true, dragStartX5: e.clientX, dragStartY5: e.clientY, dragOffsetStartX5: this.state.offsetX5, dragOffsetStartY5: this.state.offsetY5 });
  };
  onPointerMove5 = (e) => {
    if (!this.state.dragging5) return;
    const dx = e.clientX - this.state.dragStartX5;
    const dy = e.clientY - this.state.dragStartY5;
    this.setState({ offsetX5: this.state.dragOffsetStartX5 + dx, offsetY5: this.state.dragOffsetStartY5 + dy });
  };
  onPointerUp5 = () => this.setState({ dragging5: false });

  stopPropagation = (e) => e.stopPropagation();

  onKeyDown = (e) => {
    if (e.key !== "Escape") return;
    if (this.state.zoomOpen1) this.closeZoom1();
    if (this.state.zoomOpen5) this.closeZoom5();
  };

  componentDidMount() {
    document.addEventListener("keydown", this.onKeyDown);
    if (typeof document !== "undefined" && document.documentElement) {
      document.documentElement.lang = "es";
    }
  }

  componentWillUnmount() {
    document.removeEventListener("keydown", this.onKeyDown);
  }

  renderVals() {
    const s = this.state;
    return {
      zoomOpen1: s.zoomOpen1,
      openZoom1: this.openZoom1,
      closeZoom1: this.closeZoom1,
      zoomInHandler1: this.zoomIn1,
      zoomOutHandler1: this.zoomOut1,
      onWheel1: this.onWheel1,
      onPointerDown1: this.onPointerDown1,
      onPointerMove1: this.onPointerMove1,
      onPointerUp1: this.onPointerUp1,
      zoomInDisabled1: s.scale1 >= 4,
      zoomOutDisabled1: s.scale1 <= 1,
      zoomPercent1: Math.round(s.scale1 * 100) + "%",
      imgTransform1: `translate(${s.offsetX1}px, ${s.offsetY1}px) scale(${s.scale1})`,
      imgCursor1: s.scale1 > 1 ? (s.dragging1 ? "grabbing" : "grab") : "default",

      zoomOpen5: s.zoomOpen5,
      openZoom5: this.openZoom5,
      closeZoom5: this.closeZoom5,
      zoomInHandler5: this.zoomIn5,
      zoomOutHandler5: this.zoomOut5,
      onWheel5: this.onWheel5,
      onPointerDown5: this.onPointerDown5,
      onPointerMove5: this.onPointerMove5,
      onPointerUp5: this.onPointerUp5,
      zoomInDisabled5: s.scale5 >= 4,
      zoomOutDisabled5: s.scale5 <= 1,
      zoomPercent5: Math.round(s.scale5 * 100) + "%",
      imgTransform5: `translate(${s.offsetX5}px, ${s.offsetY5}px) scale(${s.scale5})`,
      imgCursor5: s.scale5 > 1 ? (s.dragging5 ? "grabbing" : "grab") : "default",

      stopPropagation: this.stopPropagation
    };
  }
}
